import Combine

@Observable
class SyncMonitor {
    var syncState: SyncState = .idle
    var lastSyncDate: Date?
    var pendingChanges: Int = 0

    enum SyncState {
        case idle
        case syncing
        case error(String)
    }

    private var cancellables = Set<AnyCancellable>()

